invisible_dynamic	CREATE TABLE `invisible_dynamic` (
  `id` int NOT NULL,
  `n` int NOT NULL,
  `a` int DEFAULT NULL /*!80023 INVISIBLE */,
  `s` bigint GENERATED ALWAYS AS ((`a` * 3)) STORED /*!80023 INVISIBLE */,
  PRIMARY KEY (`id`,`n`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC
/*!50100 PARTITION BY RANGE (`n`)
(PARTITION P0 VALUES LESS THAN (10) ENGINE = InnoDB,
 PARTITION p1 VALUES LESS THAN (20) ENGINE = InnoDB,
 PARTITION empty_p VALUES LESS THAN MAXVALUE ENGINE = InnoDB) */
